import sys

s = sys.stdin.read()
has_alpha = any(c.isalpha() for c in s)

if has_alpha:
    res = []
    for c in s:
        if c.isalpha():
            res.append(c.upper() if c.islower() else c.lower())
        else:
            res.append(c)
else:
    res = s[::-1]

sys.stdout.write(''.join(res))

def fib(n):
    if n == 0:
        return 0
    if n == 1 or n == 2:
        return 1
    a, b = 1, 1
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b
