import sys

s = sys.stdin.read()

# Step 1: Toggle case
toggled = []
for ch in s:
    if ch.islower():
        toggled.append(ch.upper())
    elif ch.isupper():
        toggled.append(ch.lower())
    else:
        toggled.append(ch)
toggled = ''.join(toggled)

# Step 2: Replace vowels with the letter two positions later
result = []
for ch in toggled:
    if ch in 'aeiouAEIOU':
        result.append(chr(ord(ch) + 2))
    else:
        result.append(ch)

sys.stdout.write(''.join(result))

def find_zero_pair(lst):
    for i in range(len(lst)):
        for j in range(len(lst)):
            if i != j and lst[i] + lst[j] == 0:
                return True
    return False
